from taf.gnb.oam.coam.vdu.utilities.http_client import HttpClient


class CPConfigv1HttpClient(HttpClient):
    """ This class provides a client for the CP Config V1 API. """

    def __init__(self, base_url, connection_alias):
        super(CPConfigv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/cp-config/v1"

    def clear_rf_diagnostic_test_results(self, timeout=30):
        endpoint = '/diagnostic/rf-diagnostic-test/results'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_delete_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def reset_vdu(self, timeout=60, graceful_cell_shutdown=False):
        endpoint = '/vdu/operations/resets'
        headers = {
            "Content-Type": "application/json",
        }

        payload = {
            "gracefulCellShutdown": graceful_cell_shutdown
        }

        return self._send_post_request(endpoint=endpoint, timeout=timeout, headers=headers, json=payload)

    def get_reset_vdu_operation_status(self, operation_id, timeout=30):
        endpoint = f'/vdu/operations/resets/{operation_id}'
        return self._send_get_request(endpoint=endpoint, timeout=timeout)

