    def start_5g_downlink_test(self, nrcell_id, test_model, beam_pattern_id, polarization, power_backoff, ru_mode,
                               phys_cell_id, codebook_2_antports, i11_codebook_4_antports, i2_codebook_4_antports,
                               i13_codebook_4_antports, mimo_rank, p_max=None, nrarfcn=0, nrarfcn_ul=0, nrarfcn_dl=0,
                               vswr_monitoring=False):
        endpoint = "/test-models/operations/downlink/start"
        headers = {
            'accept': 'application/json',
            'Content-Type': 'application/json',
        }

        json_data = {
            'nrCellId': nrcell_id,
            'dlTestModelParams': {
                'testModel': test_model,
                'physCellId': phys_cell_id,
                'beamPatternIdArray': beam_pattern_id,
                'polarization': polarization,
                'powerBackoff': power_backoff,
                'ruMode': ru_mode,
                'mimoRank': mimo_rank,
                'codebook2AntPorts': codebook_2_antports,
                'i11Codebook4AntPorts': i11_codebook_4_antports,
                'i2Codebook4AntPorts': i2_codebook_4_antports,
                'i13Codebook4AntPorts': i13_codebook_4_antports,
                'nrarfcn': nrarfcn,
                'nrarfcnUl': nrarfcn_ul,
                'nrarfcnDl': nrarfcn_dl,
                'vswrMonitoring': vswr_monitoring,
            }
        }

        if p_max is not None:
            json_data['dlTestModelParams']["pMax"] = p_max

        return self._send_post_request(endpoint=endpoint, headers=headers, json=json_data)

    def get_start_5g_downlink_test_status(self, operation_id):
        endpoint = f"/test-models/operations/downlink/start/{operation_id}"
        headers = {
            "accept": "application/json"
        }

        return self._send_get_request(endpoint=endpoint, headers=headers)

    def delete_start_5g_downlink_test(self, operation_id):
        self._send_delete_request(endpoint=f"/test-models/operations/downlink/start/{operation_id}")

