    def start_5g_uplink_ccm_test_pusch(self, nrcell_id, interval, beam_pattern_id, frc_index, prb_offset,
                                       digital_out_type, digital_out_rate, ru_mode, phys_cell_id, ul_dmrs_mapping_type,
                                       bb_selector, num_uci_bits, csi_payload_bit, nrarfcn=0, nrarfcn_ul=0,
                                       nrarfcn_dl=0, digital_output_enable=False, act_high_speed_cell=False):
        endpoint = "/test-models/operations/performance/pusch/start"
        headers = {
            'accept': 'application/json',
            'Content-Type': 'application/json',
        }

        json_data = {
            'nrCellId': nrcell_id,
            'puschTestParams': {
                'frcIndex': frc_index,
                'physCellId': phys_cell_id,
                'beamPatternIdArray': beam_pattern_id,
                'prbOffset': prb_offset,
                'reportingTimeInterval': interval,
                'ruMode': ru_mode,
                'nrarfcn': nrarfcn,
                'nrarfcnUl': nrarfcn_ul,
                'nrarfcnDl': nrarfcn_dl,
                'bbSelector': bb_selector,
                'digitalOutRate': digital_out_rate,
                'digitalOutType': digital_out_type,
                'ulDmrsMappingType': ul_dmrs_mapping_type,
                'digitalOutputEnable': digital_output_enable,
                'actHighSpeedCell': act_high_speed_cell,
            }
        }

        if num_uci_bits is not None:
            json_data['puschTestParams']['numUciBits'] = num_uci_bits

        if csi_payload_bit:
            json_data['puschTestParams']['csiPayloadBit'] = csi_payload_bit

        return self._send_post_request(endpoint=endpoint, headers=headers, json=json_data)

